package com.shahboun.aqim;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;
public class DhikrSettingsActivity extends Activity{int G=Color.rgb(15,76,58),I=Color.rgb(248,244,235),T=Color.rgb(35,48,43);android.graphics.Typeface c;SharedPreferences p;LinearLayout r;int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}GradientDrawable bg(int x){GradientDrawable g=new GradientDrawable();g.setColor(x);g.setCornerRadius(dp(22));return g;}Button b(String s){Button x=new Button(this);x.setText(s);x.setAllCaps(false);x.setGravity(Gravity.CENTER);x.setBackground(bg(Color.WHITE));x.setElevation(dp(3));if(c!=null)x.setTypeface(c,1);return x;}public void onCreate(Bundle z){super.onCreate(z);p=getSharedPreferences("aqim",0);try{if(Build.VERSION.SDK_INT>=26)c=getResources().getFont(getResources().getIdentifier("cairo","font",getPackageName()));}catch(Exception e){}show();}void show(){r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(18),dp(20),dp(18),dp(30));r.setBackgroundColor(I);r.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);TextView h=new TextView(this);h.setText("تذكير الذكر");h.setTextSize(28);h.setTextColor(G);h.setGravity(Gravity.CENTER);if(c!=null)h.setTypeface(c,1);r.addView(h,new LinearLayout.LayoutParams(-1,dp(70)));Switch on=new Switch(this);on.setText("تشغيل تذكيرات الذكر على شاشة القفل");on.setChecked(p.getBoolean("dhikrReminder",true));if(c!=null)on.setTypeface(c);r.addView(on);for(int m:new int[]{10,15,30,60}){Button x=b("كل "+m+" دقيقة"+(p.getInt("dhikrInterval",10)==m?"  ✓":""));x.setOnClickListener(v->{p.edit().putInt("dhikrInterval",m).putBoolean("dhikrReminder",true).apply();DhikrReminderReceiver.scheduleNext(this);show();});add(x);}Button quiet=b("ساعات الهدوء: "+fmt(p.getInt("quietStart",1380))+" – "+fmt(p.getInt("quietEnd",360)));quiet.setOnClickListener(v->quietDialog());add(quiet);on.setOnCheckedChangeListener((v,onv)->{p.edit().putBoolean("dhikrReminder",onv).apply();if(onv)DhikrReminderReceiver.scheduleNext(this);});TextView n=new TextView(this);n.setText("لن تظهر تذكيرات الذكر خلال ساعات الهدوء. تُحسب الساعات حسب المنطقة الزمنية المعتمدة في أَقِم.");n.setTextColor(T);n.setGravity(Gravity.CENTER);n.setPadding(dp(10),dp(18),dp(10),dp(10));if(c!=null)n.setTypeface(c);r.addView(n);ScrollView s=new ScrollView(this);s.addView(r);setContentView(s);}void quietDialog(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(10),dp(20),0);EditText a=num("بداية الهدوء HHMM",p.getInt("quietStart",1380)),e=num("نهاية الهدوء HHMM",p.getInt("quietEnd",360));box.addView(a);box.addView(e);new AlertDialog.Builder(this).setTitle("ساعات الهدوء").setView(box).setPositiveButton("حفظ",(d,w)->{int s=parse(a,p.getInt("quietStart",1380)),x=parse(e,p.getInt("quietEnd",360));p.edit().putInt("quietStart",s).putInt("quietEnd",x).apply();show();}).setNegativeButton("إلغاء",null).show();}EditText num(String hint,int mins){EditText e=new EditText(this);e.setHint(hint);e.setText(String.format(java.util.Locale.US,"%02d%02d",mins/60,mins%60));e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setGravity(Gravity.CENTER);return e;}int parse(EditText e,int def){try{String x=e.getText().toString().trim();if(x.length()!=4)return def;int h=Integer.parseInt(x.substring(0,2)),m=Integer.parseInt(x.substring(2));if(h<0||h>23||m<0||m>59)return def;return h*60+m;}catch(Exception ex){return def;}}String fmt(int m){return String.format(java.util.Locale.US,"%02d:%02d",m/60,m%60);}void add(View x){LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,dp(62));q.setMargins(0,dp(9),0,0);r.addView(x,q);}}
